#include <vector>
#include <set>
#include <algorithm>

using namespace std;

class Solution {
public:
    int rectangleArea(vector<vector<int>>& rectangles) {
        const int MOD = 1e9 + 7;
        vector<int> X;
        for (auto& r : rectangles) {
            X.push_back(r[0]);
            X.push_back(r[2]);
        }

        sort(X.begin(), X.end());
        X.erase(unique(X.begin(), X.end()), X.end());

        long res = 0;
        for (int i = 1; i < X.size(); ++i) {
            int x1 = X[i - 1], x2 = X[i];
            if (x1 == x2) continue;
            vector<pair<int, int>> segs;
            for (auto& r : rectangles)
                if (r[0] <= x1 && r[2] >= x2)
                    segs.emplace_back(r[1], r[3]);

            sort(segs.begin(), segs.end());
            int total = 0, start = -1, end = -1;
            for (auto& [y1, y2] : segs) {
                start = max(start, y1);
                if (y2 > end) {
                    total += y2 - max(end, y1);
                    end = y2;
                }
            }
            res = (res + (long)(x2 - x1) * total) % MOD;
        }

        return res;
    }
};
